// ─── File: PrototypeDemo.java ───
package com.bank.prototype;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class PrototypeDemo {
    private static final Logger log = Logger.getLogger(PrototypeDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch); root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // One standard NSE template (the prototype) with shared defaults
        OrderPrototype template = new OrderPrototype("NSE", new BigDecimal("0.0010"), "T+1");
        log.info(() -> "Prototype template: " + template);

        // Rajesh's order: copy the template, change only what differs
        OrderPrototype rajesh = template.copy();
        rajesh.setAccountId("SAV2001");
        rajesh.setSymbol("RELIANCE");
        rajesh.setQuantity(100);
        rajesh.addLeg(new OrderLeg("BUY", 100));     // mutates the COPY's leg list only

        // Priya's order: another independent copy
        OrderPrototype priya = template.copy();
        priya.setAccountId("CUR3001");
        priya.setSymbol("TCS");
        priya.setQuantity(25);

        log.info(() -> "Rajesh order: " + rajesh);
        log.info(() -> "Priya  order: " + priya);
        // Prove deep copy: template legs still empty, Priya legs still empty
        log.info(() -> "Template legs after copies: " + template.getLegs().size() + " (expect 0)");
        log.info(() -> "Priya legs (independent)  : " + priya.getLegs().size() + " (expect 0)");
    }
}

// ─── Mutable nested object: must be deep-copied ───
class OrderLeg {
    private final String side; private final int qty;
    OrderLeg(String side, int qty) { this.side = side; this.qty = qty; }
    OrderLeg copy() { return new OrderLeg(side, qty); }
    public String toString() { return side + ":" + qty; }
}

// ─── The prototype: copy constructor does a DEEP copy of the leg list ───
class OrderPrototype {
    private final String exchange;             // shared default
    private final BigDecimal defaultFeeRate;    // shared default
    private final String settlementCycle;       // shared default
    private String accountId, symbol;
    private int quantity;
    private final List<OrderLeg> legs;

    OrderPrototype(String exchange, BigDecimal feeRate, String cycle) {
        this.exchange = exchange; this.defaultFeeRate = feeRate; this.settlementCycle = cycle;
        this.legs = new ArrayList<>();
    }
    // copy constructor: DEEP copy so copies are independent
    private OrderPrototype(OrderPrototype o) {
        this.exchange = o.exchange; this.defaultFeeRate = o.defaultFeeRate; this.settlementCycle = o.settlementCycle;
        this.accountId = o.accountId; this.symbol = o.symbol; this.quantity = o.quantity;
        this.legs = new ArrayList<>();                 // NEW list, not shared
        for (OrderLeg leg : o.legs) this.legs.add(leg.copy());  // deep-copy each leg
    }
    OrderPrototype copy() { return new OrderPrototype(this); }

    void setAccountId(String v){ this.accountId=v; } void setSymbol(String v){ this.symbol=v; }
    void setQuantity(int v){ this.quantity=v; } void addLeg(OrderLeg l){ this.legs.add(l); }
    List<OrderLeg> getLegs(){ return legs; }
    public String toString() {
        return exchange + " rate=" + defaultFeeRate + " cycle=" + settlementCycle
             + " acct=" + accountId + " sym=" + symbol + " qty=" + quantity + " legs=" + legs;
    }
}

class BankLogFormatter extends Formatter {
    public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
